/**
 * Direct audio uploads, end to end over real HTTP: the signed form
 * (`POST /api/audio-uploads`, `POST /api/podcasts/episodes/:id/ingest/upload`)
 * and the four routes completing an upload by `uploadId` instead of a body.
 *
 * Only STORAGE is faked — an in-memory bucket behind `s3Service`'s own
 * functions. The presigned PUT is generated by the REAL signer (with a static
 * test credential), and everything a completing route runs —
 * ffprobe, the tag reader, dedup, ownership checks, the rows, the ticket claim —
 * runs for real against real Postgres and real fixtures, so an outcome asserted
 * here is one the pipeline actually produced.
 *
 * `mock.module` is process-global, so every fake is ARMED only while this file
 * runs and otherwise delegates to the real implementation captured BY VALUE
 * before the mocks are registered (see `podcastEpisodeMetadata.test.ts` for why
 * a live binding would re-enter the fake).
 */

import { afterAll, afterEach, beforeAll, describe, expect, it, mock } from 'bun:test';
import express from 'express';
import fs from 'node:fs';
import path from 'node:path';
import { Readable } from 'node:stream';
import type { Server } from 'node:http';
import { eq } from 'drizzle-orm';
import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import { uuidv7 } from '@oxy.so/db';
import type { OxyAuthRequest as AuthRequest } from '@oxy.so/core/server';
import { normalizeNameKey, type AudioUploadTarget } from '@syra/shared-types';
import { clearDb, connectDb, disconnectDb } from '../test/postgres';
import { getDb } from '../db/postgres';
import { catalogEntities, tracks } from '../db/schema/catalog';
import { userUploads } from '../db/schema/creators';
import { episodeIngestTickets, episodes, podcasts } from '../db/schema/podcasts';
import * as realS3 from '../services/s3Service';
import * as realIngestQueue from '../services/ingest/ingestQueue';
import * as realEpisodeIngest from '../services/podcasts/ingestEpisode';
import {
  ABANDONED_UPLOAD_AGE_MS,
  sweepAbandonedAudioUploads,
} from '../services/uploads/directAudioUpload';
import audioUploadsRoutes from './audioUploads.routes';
import uploadsRoutes from './uploads.routes';
import tracksRoutes from './tracks.routes';
import podcastsRoutes from './podcasts.routes';

process.env.INGEST_TOKEN_SECRET = 'test-secret-direct-audio-upload';

// ── The in-memory bucket ─────────────────────────────────────────────────────

const real = {
  createPresignedUpload: realS3.createPresignedUpload,
  getObjectMetadata: realS3.getObjectMetadata,
  streamFromS3: realS3.streamFromS3,
  copyWithinS3: realS3.copyWithinS3,
  uploadToS3: realS3.uploadToS3,
  deleteFromS3: realS3.deleteFromS3,
  deleteFromS3Batch: realS3.deleteFromS3Batch,
  listS3Objects: realS3.listS3Objects,
};
const realEnqueueIngest = realIngestQueue.enqueueIngest;
const realEnqueueUploadIngest = realIngestQueue.enqueueUploadIngest;
const realEnqueueEpisodeIngest = realEpisodeIngest.enqueueEpisodeIngest;

let armed = false;

interface StoredObject {
  body: Buffer;
  contentType: string;
  /** Overrides `body.length` — a 600 MB object without 600 MB of memory. */
  reportedSize?: number;
  metadata?: Record<string, string>;
  lastModified: Date;
}
const bucket = new Map<string, StoredObject>();
const uploadedKeys: string[] = [];
const copies: Array<{ from: string; to: string; options: realS3.S3UploadOptions | undefined }> = [];
const deletedKeys: string[] = [];
const enqueued: string[] = [];

/** The static credential the real signer uses here: no AWS chain is consulted. */
const signingClient = new S3Client({
  region: 'us-west-2',
  forcePathStyle: true,
  credentials: { accessKeyId: 'AKIATEST', secretAccessKey: 'secret', sessionToken: 'session' },
});
const TEST_BUCKET = 'syra-test';

mock.module('../services/s3Service', () => ({
  ...realS3,
  createPresignedUpload: async (key: string, options: realS3.PresignedUploadOptions) => {
    if (!armed) return real.createPresignedUpload(key, options);
    const url = await getSignedUrl(
      signingClient,
      new PutObjectCommand({
        Bucket: TEST_BUCKET,
        Key: key,
        ContentType: options.contentType,
        ContentLength: options.contentLength,
      }),
      {
        expiresIn: options.expiresInSeconds,
        signableHeaders: new Set(['content-type', 'content-length']),
      },
    );
    return { url, headers: { 'Content-Type': options.contentType } };
  },
  getObjectMetadata: async (key: string) => {
    if (!armed) return real.getObjectMetadata(key);
    const object = bucket.get(key);
    if (!object) return null;
    return {
      contentLength: object.reportedSize ?? object.body.length,
      contentType: object.contentType,
      lastModified: object.lastModified,
    };
  },
  streamFromS3: async (key: string, options?: realS3.S3StreamOptions) => {
    if (!armed) return real.streamFromS3(key, options);
    const object = bucket.get(key);
    if (!object) throw new Error(`fake bucket: no object ${key}`);
    return {
      stream: Readable.from(object.body),
      contentLength: object.body.length,
      contentType: object.contentType,
    };
  },
  copyWithinS3: async (from: string, to: string, options?: realS3.S3UploadOptions) => {
    if (!armed) return real.copyWithinS3(from, to, options);
    const object = bucket.get(from);
    if (!object) throw new Error(`fake bucket: no object ${from}`);
    copies.push({ from, to, options });
    bucket.set(to, { ...object, contentType: options?.contentType ?? object.contentType });
  },
  uploadToS3: async (key: string, body: unknown, options?: realS3.S3UploadOptions) => {
    if (!armed) {
      return real.uploadToS3(key, body as Parameters<typeof real.uploadToS3>[1], options);
    }
    // Drained the way the real client drains it: the route removes the temp
    // file as soon as this returns.
    if (body && typeof body === 'object' && Symbol.asyncIterator in body) {
      for await (const _chunk of body as AsyncIterable<unknown>) {
        // drained
      }
    }
    uploadedKeys.push(key);
  },
  deleteFromS3: async (key: string) => {
    if (!armed) return real.deleteFromS3(key);
    deletedKeys.push(key);
    bucket.delete(key);
  },
  deleteFromS3Batch: async (keys: readonly string[]) => {
    if (!armed) return real.deleteFromS3Batch(keys);
    for (const key of keys) {
      deletedKeys.push(key);
      bucket.delete(key);
    }
    return keys.length;
  },
  listS3Objects: (prefix: string) => {
    if (!armed) return real.listS3Objects(prefix);
    return (async function* () {
      for (const [key, object] of bucket) {
        if (key.startsWith(prefix)) yield { key, lastModified: object.lastModified };
      }
    })();
  },
}));

mock.module('../services/ingest/ingestQueue', () => ({
  ...realIngestQueue,
  enqueueIngest: async (trackId: string) => {
    if (!armed) return realEnqueueIngest(trackId);
    enqueued.push(trackId);
  },
  enqueueUploadIngest: async (uploadId: string) => {
    if (!armed) return realEnqueueUploadIngest(uploadId);
    enqueued.push(uploadId);
  },
}));

mock.module('../services/podcasts/ingestEpisode', () => ({
  ...realEpisodeIngest,
  enqueueEpisodeIngest: (episodeId: string) => {
    if (!armed) {
      realEnqueueEpisodeIngest(episodeId);
      return;
    }
    enqueued.push(episodeId);
  },
}));

// ── Server ───────────────────────────────────────────────────────────────────

const FIXTURES = path.join(__dirname, '../services/uploads/__fixtures__');
const OWNER = 'oxydirectowner';
const STRANGER = 'oxydirectstranger';
const VIEWER_HEADER = 'x-test-viewer';
const TICKET_HEADER = 'x-ingest-ticket';

let server: Server;
let baseUrl: string;

beforeAll(async () => {
  await connectDb();
  armed = true;

  const app = express();
  app.use(express.json());
  app.use((req, _res, next) => {
    const viewer = req.headers[VIEWER_HEADER];
    if (typeof viewer === 'string' && viewer.length > 0) {
      (req as AuthRequest).user = { id: viewer };
      (req as AuthRequest).accessToken = `verified-session:${viewer}`;
    }
    next();
  });
  app.use('/api/audio-uploads', audioUploadsRoutes);
  app.use('/api/uploads', uploadsRoutes);
  app.use('/api/tracks', tracksRoutes);
  app.use('/api/podcasts', podcastsRoutes);

  server = await new Promise<Server>((resolve) => {
    const listening = app.listen(0, () => resolve(listening));
  });
  const address = server.address();
  if (!address || typeof address === 'string') throw new Error('no test server address');
  baseUrl = `http://127.0.0.1:${address.port}`;
});

afterEach(async () => {
  await clearDb();
  bucket.clear();
  uploadedKeys.length = 0;
  copies.length = 0;
  deletedKeys.length = 0;
  enqueued.length = 0;
});

afterAll(async () => {
  armed = false;
  await new Promise<void>((resolve) => server.close(() => resolve()));
  await disconnectDb();
});

// ── Helpers ──────────────────────────────────────────────────────────────────

async function post(
  url: string,
  body: Record<string, unknown>,
  headers: Record<string, string> = {},
): Promise<{ status: number; body: Record<string, unknown> }> {
  const response = await fetch(`${baseUrl}${url}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', ...headers },
    body: JSON.stringify(body),
  });
  return { status: response.status, body: (await response.json()) as Record<string, unknown> };
}

/** Step 1, as `viewer`. */
async function requestTarget(
  body: Record<string, unknown>,
  viewer: string = OWNER,
): Promise<{ status: number; body: Record<string, unknown> }> {
  return post('/api/audio-uploads', body, { [VIEWER_HEADER]: viewer });
}

function targetOf(body: Record<string, unknown>): AudioUploadTarget {
  return body.data as AudioUploadTarget;
}

/** The object key a presigned URL admits (path-style: `/{bucket}/{key}`). */
function keyOf(target: AudioUploadTarget): string {
  const path = decodeURIComponent(new URL(target.url).pathname);
  return path.slice(`/${TEST_BUCKET}/`.length);
}

/**
 * Step 2, as storage would record it: the object the presigned URL admits, at
 * the key it names, with the type it fixes.
 */
function sendToStorage(target: AudioUploadTarget, fixture: string): string {
  const key = keyOf(target);
  const contentType = target.headers['Content-Type'];
  if (!contentType) throw new Error('the presigned PUT fixes no type');
  bucket.set(key, {
    body: fs.readFileSync(path.join(FIXTURES, fixture)),
    contentType,
    lastModified: new Date(),
  });
  return key;
}

async function makeArtist(owner: string): Promise<string> {
  const name = `Direct Artist ${uuidv7()}`;
  const [artist] = await getDb()
    .insert(catalogEntities)
    .values({
      type: 'artist',
      name,
      nameKey: normalizeNameKey(name),
      source: 'upload',
      ownerOxyUserId: owner,
    })
    .returning({ id: catalogEntities.id });
  if (!artist) throw new Error('makeArtist: insert returned no row');
  return artist.id;
}

async function seedShow(owner: string = OWNER): Promise<string> {
  const id = uuidv7();
  await getDb()
    .insert(podcasts)
    .values({
      id,
      title: 'Direct Show',
      source: 'syra',
      status: 'active',
      ownerOxyUserId: owner,
      feedUrl: `https://feeds.example.invalid/${id}.xml`,
    });
  return id;
}

// ── Step 1: the signed form ──────────────────────────────────────────────────

describe('POST /api/audio-uploads', () => {
  it('signs a PUT for ONE object, under the caller’s own key, of exactly its type and size', async () => {
    const { status, body } = await requestTarget({
      purpose: 'track',
      mimeType: 'audio/flac',
      sizeBytes: 150 * 1024 * 1024,
    });

    expect(status).toBe(201);
    const target = targetOf(body);
    expect(target.method).toBe('PUT');
    expect(target.maxBytes).toBe(200 * 1024 * 1024);
    expect(keyOf(target)).toBe(`incoming/track/account/${OWNER}/${target.uploadId}`);
    expect(target.headers).toEqual({ 'Content-Type': 'audio/flac' });
    expect(Date.parse(target.expiresAt)).toBeGreaterThan(Date.now());

    // What storage enforces is the SIGNATURE: a body of another length, or
    // another declared type, no longer matches it.
    const signed = new URL(target.url).searchParams.get('X-Amz-SignedHeaders')?.split(';');
    expect(signed).toEqual(expect.arrayContaining(['content-length', 'content-type', 'host']));
  });

  it('caps an episode at 500 MB, the route’s own limit', async () => {
    const { status, body } = await requestTarget({
      purpose: 'episode',
      mimeType: 'audio/mpeg',
      sizeBytes: 450 * 1024 * 1024,
    });
    expect(status).toBe(201);
    expect(targetOf(body).maxBytes).toBe(500 * 1024 * 1024);
  });

  it('refuses a declared size over the cap BEFORE anything is transferred', async () => {
    const over = await requestTarget({
      purpose: 'locker',
      mimeType: 'audio/mpeg',
      sizeBytes: 200 * 1024 * 1024 + 1,
    });
    expect(over.status).toBe(413);

    // Control: the same size is fine for the route that takes 500 MB.
    const episode = await requestTarget({
      purpose: 'episode',
      mimeType: 'audio/mpeg',
      sizeBytes: 200 * 1024 * 1024 + 1,
    });
    expect(episode.status).toBe(201);
  });

  it('refuses a type the multipart routes refuse', async () => {
    const refused = await requestTarget({
      purpose: 'locker',
      mimeType: 'video/mp4',
      sizeBytes: 10,
    });
    expect(refused.status).toBe(400);
    expect(refused.body.message).toMatch(/Only audio files/);
  });

  it('refuses an unknown purpose, a missing size, and a caller with no session', async () => {
    expect(
      (await requestTarget({ purpose: 'avatar', mimeType: 'audio/mpeg', sizeBytes: 10 })).status,
    ).toBe(400);
    expect((await requestTarget({ purpose: 'track', mimeType: 'audio/mpeg' })).status).toBe(400);
    expect(
      (await requestTarget({ purpose: 'track', mimeType: 'audio/mpeg', sizeBytes: 10 }, '')).status,
    ).toBe(401);
  });
});

// ── Step 3: the locker ───────────────────────────────────────────────────────

describe('POST /api/uploads by uploadId', () => {
  it('runs the locker pipeline on the uploaded object and answers exactly as multipart does', async () => {
    const target = targetOf(
      (await requestTarget({ purpose: 'locker', mimeType: 'audio/wav', sizeBytes: 4096 })).body,
    );
    sendToStorage(target, 'untagged.wav');

    const { status, body } = await post(
      '/api/uploads',
      { uploadId: target.uploadId, fileName: 'Field Recording.wav', destination: 'private' },
      { [VIEWER_HEADER]: OWNER },
    );

    expect(status).toBe(201);
    expect(body.outcome).toBe('stored');
    const upload = body.upload as { id: string; title: string };
    // ffprobe read the staged copy: the row has the file's real duration.
    const [row] = await getDb().select().from(userUploads).where(eq(userUploads.id, upload.id));
    expect(row?.duration).toBeGreaterThan(0);
    // An untagged file is titled from the name it had on the uploader's device.
    expect(upload.title).toBe('Field Recording');
    // The ORIGINAL went where a multipart upload's always went…
    expect(uploadedKeys).toEqual([`uploads/${OWNER}/${upload.id}.wav`]);
    expect(enqueued).toEqual([upload.id]);
    // …and the incoming object is gone.
    expect(bucket.has(keyOf(target))).toBe(false);
  });

  it('cannot complete somebody else’s upload — the key is derived from the caller', async () => {
    const target = targetOf(
      (await requestTarget({ purpose: 'locker', mimeType: 'audio/wav', sizeBytes: 4096 })).body,
    );
    sendToStorage(target, 'untagged.wav');

    const stranger = await post(
      '/api/uploads',
      { uploadId: target.uploadId, destination: 'private' },
      { [VIEWER_HEADER]: STRANGER },
    );
    expect(stranger.status).toBe(400);
    expect(stranger.body.error).toBe('Upload not found');
    // Not theirs, so not theirs to delete either.
    expect(bucket.has(keyOf(target))).toBe(true);
    expect(await getDb().select().from(userUploads)).toHaveLength(0);

    // Control: the owner completes the same upload.
    const owner = await post(
      '/api/uploads',
      { uploadId: target.uploadId, destination: 'private' },
      { [VIEWER_HEADER]: OWNER },
    );
    expect(owner.status).toBe(201);
  });

  it('refuses an object over the cap and deletes it', async () => {
    const target = targetOf(
      (await requestTarget({ purpose: 'locker', mimeType: 'audio/wav', sizeBytes: 4096 })).body,
    );
    const key = sendToStorage(target, 'untagged.wav');
    const stored = bucket.get(key);
    if (!stored) throw new Error('fixture not stored');
    stored.reportedSize = 200 * 1024 * 1024 + 1;

    const { status, body } = await post(
      '/api/uploads',
      { uploadId: target.uploadId, destination: 'private' },
      { [VIEWER_HEADER]: OWNER },
    );
    expect(status).toBe(413);
    expect(body.message).toBe('File too large');
    expect(bucket.has(key)).toBe(false);
    expect(uploadedKeys).toEqual([]);
  });

  it('refuses an object whose stored type is not audio, and deletes it', async () => {
    const target = targetOf(
      (await requestTarget({ purpose: 'locker', mimeType: 'audio/wav', sizeBytes: 4096 })).body,
    );
    const key = sendToStorage(target, 'untagged.wav');
    const stored = bucket.get(key);
    if (!stored) throw new Error('fixture not stored');
    stored.contentType = 'application/octet-stream';

    const { status } = await post(
      '/api/uploads',
      { uploadId: target.uploadId, destination: 'private' },
      { [VIEWER_HEADER]: OWNER },
    );
    expect(status).toBe(400);
    expect(bucket.has(key)).toBe(false);
  });

  it('refuses an uploadId that is not one this API minted', async () => {
    const { status, body } = await post(
      '/api/uploads',
      { uploadId: '../../audio/somebody/else', destination: 'private' },
      { [VIEWER_HEADER]: OWNER },
    );
    expect(status).toBe(400);
    expect(body.error).toBe('Invalid upload');
  });

  it('still answers "file required" when the request names no file at all', async () => {
    const { status, body } = await post(
      '/api/uploads',
      { destination: 'private' },
      { [VIEWER_HEADER]: OWNER },
    );
    expect(status).toBe(400);
    expect(body.error).toBe('Missing file');
  });
});

// ── Step 3: a creator's track ────────────────────────────────────────────────

describe('POST /api/tracks/upload by uploadId', () => {
  it('creates the track from the uploaded object, probed for its real duration', async () => {
    const artistId = await makeArtist(OWNER);
    const target = targetOf(
      (await requestTarget({ purpose: 'track', mimeType: 'audio/mpeg', sizeBytes: 4096 })).body,
    );
    sendToStorage(target, 'indie-id3v2.mp3');

    const { status, body } = await post(
      '/api/tracks/upload',
      { uploadId: target.uploadId, title: 'Direct Song', artistId, genre: ['folk'] },
      { [VIEWER_HEADER]: OWNER },
    );

    expect(status).toBe(201);
    expect(body.title).toBe('Direct Song');
    expect(body.duration).toBeGreaterThan(0);
    const trackId = String(body.id);
    expect(uploadedKeys).toEqual([`audio/${artistId}/${trackId}.mp3`]);
    expect(enqueued).toEqual([trackId]);
    const [row] = await getDb().select().from(tracks).where(eq(tracks.id, trackId));
    expect(row?.metadataGenre).toEqual(['folk']);
    expect(bucket.has(keyOf(target))).toBe(false);
  });

  it('keeps the ownership check — a stranger’s artist is refused and the upload discarded', async () => {
    const artistId = await makeArtist(OWNER);
    const target = targetOf(
      (await requestTarget({ purpose: 'track', mimeType: 'audio/mpeg', sizeBytes: 4096 }, STRANGER))
        .body,
    );
    sendToStorage(target, 'indie-id3v2.mp3');

    const { status } = await post(
      '/api/tracks/upload',
      { uploadId: target.uploadId, title: 'Not Mine', artistId },
      { [VIEWER_HEADER]: STRANGER },
    );
    expect(status).toBe(403);
    expect(uploadedKeys).toEqual([]);
    expect(bucket.has(keyOf(target))).toBe(false);
  });
});

// ── Step 3: an episode ───────────────────────────────────────────────────────

describe('POST /api/podcasts/:id/episodes by uploadId', () => {
  it('copies the upload to the episode’s key, owned by its uploader, without a byte through the API', async () => {
    const showId = await seedShow();
    const target = targetOf(
      (await requestTarget({ purpose: 'episode', mimeType: 'audio/mpeg', sizeBytes: 4096 })).body,
    );
    sendToStorage(target, 'indie-id3v2.mp3');

    const { status, body } = await post(
      `/api/podcasts/${showId}/episodes`,
      { uploadId: target.uploadId, title: 'Direct Episode', season: 2, explicit: true },
      { [VIEWER_HEADER]: OWNER },
    );

    expect(status).toBe(201);
    const episode = body.data as { id: string; title: string; season?: number };
    expect(episode.title).toBe('Direct Episode');
    expect(episode.season).toBe(2);
    expect(copies).toEqual([
      {
        from: keyOf(target),
        to: `podcasts/audio/${showId}/${episode.id}.mp3`,
        options: { contentType: 'audio/mpeg', metadata: { 'oxy-owner': `account:${OWNER}` } },
      },
    ]);
    expect(uploadedKeys).toEqual([]);
    expect(enqueued).toEqual([episode.id]);
    expect(bucket.has(keyOf(target))).toBe(false);
  });
});

// ── The ingest ticket ────────────────────────────────────────────────────────

describe('the ingest ticket, uploading directly', () => {
  async function draft(showId: string): Promise<{ episodeId: string; ingestTicket: string }> {
    const { status, body } = await post(
      `/api/podcasts/${showId}/episodes/draft`,
      { title: 'Drafted' },
      { [VIEWER_HEADER]: OWNER },
    );
    if (status !== 201) throw new Error(`draft failed: ${status}`);
    return body.data as { episodeId: string; ingestTicket: string };
  }

  it('signs a form for the ticket’s episode, spends nothing, and redeems by uploadId', async () => {
    const showId = await seedShow();
    const { episodeId, ingestTicket } = await draft(showId);

    const signed = await post(
      `/api/podcasts/episodes/${episodeId}/ingest/upload`,
      { mimeType: 'audio/mpeg', sizeBytes: 300 * 1024 * 1024 },
      { [TICKET_HEADER]: ingestTicket },
    );
    expect(signed.status).toBe(201);
    const target = targetOf(signed.body);
    expect(keyOf(target)).toBe(`incoming/episode/ticket/${episodeId}/${target.uploadId}`);
    // Asking for a form is not a redemption.
    const [ticket] = await getDb()
      .select()
      .from(episodeIngestTickets)
      .where(eq(episodeIngestTickets.episodeId, episodeId));
    expect(ticket?.consumedAt).toBeNull();

    sendToStorage(target, 'indie-id3v2.mp3');
    const redeemed = await post(
      `/api/podcasts/episodes/${episodeId}/ingest`,
      { uploadId: target.uploadId, title: 'Finished Episode', duration: 1234 },
      { [TICKET_HEADER]: ingestTicket },
    );
    expect(redeemed.status).toBe(202);
    expect(copies.map((copy) => copy.to)).toEqual([`podcasts/audio/${showId}/${episodeId}.mp3`]);
    expect(copies[0]?.options?.metadata).toEqual({ 'oxy-owner': `account:${OWNER}` });
    expect(enqueued).toEqual([episodeId]);
    const [row] = await getDb().select().from(episodes).where(eq(episodes.id, episodeId));
    expect(row?.title).toBe('Finished Episode');
    expect(row?.duration).toBe(1234);
    expect(bucket.has(keyOf(target))).toBe(false);

    // Single use, exactly as the multipart redemption is.
    const replay = await post(
      `/api/podcasts/episodes/${episodeId}/ingest`,
      { uploadId: target.uploadId },
      { [TICKET_HEADER]: ingestTicket },
    );
    expect(replay.status).toBe(409);
    // …and a spent ticket cannot keep obtaining upload forms.
    const again = await post(
      `/api/podcasts/episodes/${episodeId}/ingest/upload`,
      { mimeType: 'audio/mpeg', sizeBytes: 10 },
      { [TICKET_HEADER]: ingestTicket },
    );
    expect(again.status).toBe(409);
  });

  it('refuses a form without a valid ticket', async () => {
    const showId = await seedShow();
    const { episodeId } = await draft(showId);
    const missing = await post(`/api/podcasts/episodes/${episodeId}/ingest/upload`, {
      mimeType: 'audio/mpeg',
      sizeBytes: 10,
    });
    expect(missing.status).toBe(401);
    const forged = await post(
      `/api/podcasts/episodes/${episodeId}/ingest/upload`,
      { mimeType: 'audio/mpeg', sizeBytes: 10 },
      { [TICKET_HEADER]: 'not-a-ticket' },
    );
    expect(forged.status).toBe(401);
  });

  it('does not let a ticket complete an upload signed for a signed-in account', async () => {
    const showId = await seedShow();
    const { episodeId, ingestTicket } = await draft(showId);
    // The show owner's own form — under `account/`, not `ticket/`.
    const target = targetOf(
      (await requestTarget({ purpose: 'episode', mimeType: 'audio/mpeg', sizeBytes: 4096 })).body,
    );
    sendToStorage(target, 'indie-id3v2.mp3');

    const { status, body } = await post(
      `/api/podcasts/episodes/${episodeId}/ingest`,
      { uploadId: target.uploadId },
      { [TICKET_HEADER]: ingestTicket },
    );
    expect(status).toBe(400);
    expect(body.error).toBe('Upload not found');
    // Refused before the claim: the ticket is still good.
    const [ticket] = await getDb()
      .select()
      .from(episodeIngestTickets)
      .where(eq(episodeIngestTickets.episodeId, episodeId));
    expect(ticket?.consumedAt).toBeNull();
  });
});

// ── Abandoned uploads ────────────────────────────────────────────────────────

describe('sweepAbandonedAudioUploads', () => {
  it('deletes incoming objects older than a day, and nothing younger or outside incoming/', async () => {
    const now = new Date();
    const old = new Date(now.getTime() - ABANDONED_UPLOAD_AGE_MS - 1000);
    const fresh = new Date(now.getTime() - 60_000);
    const object = (lastModified: Date): StoredObject => ({
      body: Buffer.from('x'),
      contentType: 'audio/mpeg',
      lastModified,
    });
    bucket.set('incoming/track/account/a/old', object(old));
    bucket.set('incoming/track/account/a/fresh', object(fresh));
    bucket.set('audio/artist/track.mp3', object(old));

    expect(await sweepAbandonedAudioUploads(now)).toBe(1);
    expect([...bucket.keys()].sort()).toEqual([
      'audio/artist/track.mp3',
      'incoming/track/account/a/fresh',
    ]);
  });
});
